import type { Metric } from '@witness/gate';
import { Code, Status, type SourceEvent, type TraceHeader, type TraceLine } from './events.js';

/**
 * SYNTHETIC demo traces. These are generated by Witness to drive the UI and
 * tests without a camera or Presage credits. They are NOT SmartSpectra
 * output, and nothing measured from them may be reported as a result. The
 * app shows "Replay · synthetic" whenever one is playing.
 *
 * They do model documented SDK behaviour qualitatively: warm-up (confidence 0
 * until each window fills), CAMERA_TUNING at start, and, for the
 * contamination scenarios, the documented failure mode of readings staying
 * `stable` while a condition the SDK has no warning code for is present.
 */
export const SCENARIOS = {
  clean: 'Still, quiet, steady light',
  talking: 'Reads aloud from 35 s to 50 s',
  flicker72: 'Room light pulses at 72/min from 3 s',
  multiple_faces: 'A second face appears at 25–28 s',
  motion: 'Head turns at 20–23 s',
  chewing: 'Chews gum from 10 s to 32 s',
  photo: 'A printed photo instead of a person',
} as const;

export type Scenario = keyof typeof SCENARIOS;

/** Where each scenario's condition is, for drawing condition bands (matches the generator below). */
export const SCENARIO_LABELS: Record<Scenario, { condition: string; fromS: number; toS: number | null }[]> = {
  clean: [],
  talking: [{ condition: 'talking', fromS: 35, toS: 50 }],
  flicker72: [{ condition: 'flicker', fromS: 3, toS: null }],
  multiple_faces: [{ condition: 'second_person', fromS: 25, toS: 28 }],
  motion: [{ condition: 'motion', fromS: 20, toS: 23 }],
  chewing: [{ condition: 'chewing', fromS: 10, toS: 32 }],
  photo: [{ condition: 'photo', fromS: 0, toS: null }],
};

function rng(seed: number) {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const WIN: Record<Metric, number> = { pulse: 12, breathing: 30, hrv: 60 };
const STABLE_AT: Record<Metric, number> = { pulse: 40, breathing: 45, hrv: 50 };

export function syntheticTrace(scenario: Scenario, o: { mode?: 'quick' | 'full'; durS?: number; seed?: number } = {}): TraceLine[] {
  const mode = o.mode ?? 'full';
  const durS = o.durS ?? (mode === 'quick' ? 30 : 80);
  const r = rng(o.seed ?? 11);
  const g = () => Math.sqrt(-2 * Math.log(r() + 1e-12)) * Math.cos(2 * Math.PI * r());
  const US = 1e6;
  const fps = 30;
  const header: TraceHeader = {
    type: 'header', v: 1, source: `synthetic:${scenario}`, synthetic: true, sdkVersion: 'synthetic', mode,
    note: 'Synthetic illustrative data generated by Witness. Not SmartSpectra output; never report numbers from it.',
  };
  const ev: SourceEvent[] = [{ type: 'status', t: 0, status: Status.starting }, { type: 'status', t: 300_000, status: Status.running }];
  const between = (s: number, a: number, b: number) => s >= a && s < b;

  const truth = { pulse: 68, breathing: 13, hrv: 42 };
  // validation: tuning, then OK; scenario episodes; re-sent once a second like a heartbeat
  const codeAt = (s: number): [number, string] => {
    if (s < 2) return [Code.cameraTuning, 'Adjusting the camera…'];
    if (scenario === 'multiple_faces' && between(s, 25, 28)) return [Code.multipleFaces, 'More than one face in view'];
    return [Code.ok, ''];
  };
  let lastCode = -1;
  for (let k = 0; k < durS * 10; k++) {
    const s = k / 10;
    const [code, hint] = codeAt(s);
    if (code !== lastCode || k % 10 === 0) ev.push({ type: 'validation', t: Math.round(s * US), code, hint });
    lastCode = code;
  }
  const blinkEvery = 3.7;
  let nextBlink = 1.5;
  for (let k = 0; k < durS * fps; k++) {
    const s = k / fps;
    const t = Math.round(s * US);
    const talking = scenario === 'talking' && between(s, 35, 50);
    let blinking = false;
    if (scenario !== 'photo' && s >= nextBlink) {
      blinking = true;
      nextBlink += blinkEvery + r();
    }
    const reset = scenario === 'multiple_faces' && Math.abs(s - 25) < 0.5 / fps;
    ev.push({ type: 'face', t, talking, blinking, landmarksReset: reset });
    const moving = scenario === 'motion' && between(s, 20, 23);
    const chewing = scenario === 'chewing' && between(s, 10, 32);
    const motion = scenario === 'photo' ? 0 : moving ? 0.04 + 0.03 * Math.abs(g()) : 0.0015 + 0.0008 * Math.abs(g());
    const mouth = 0.05 + 0.002 * g() + (chewing ? 0.03 * Math.sin(2 * Math.PI * 1.4 * s) : 0) + (talking ? 0.05 * Math.abs(Math.sin(2 * Math.PI * 3.1 * s)) : 0);
    const jaw = 1 + 0.002 * g() + (chewing ? 0.02 * Math.sin(2 * Math.PI * 1.4 * s) : 0);
    ev.push({ type: 'face_feature', t, motion: k === 0 ? null : motion, mouth, jaw });
    const flick = scenario === 'flicker72' && s >= 3 ? 1 + 0.012 * Math.sin(2 * Math.PI * 1.2 * s) : 1;
    ev.push({ type: 'frame', t, bg: [118 * flick + 0.15 * g(), 121 * flick + 0.15 * g()], chest: 70, face: 140 + 0.4 * Math.sin(2 * Math.PI * (truth.pulse / 60) * s) });
    ev.push({ type: 'trace', t, kind: 'pulse', value: Math.sin(2 * Math.PI * (truth.pulse / 60) * s) + 0.25 * Math.sin(4 * Math.PI * (truth.pulse / 60) * s + 0.8) });
    if (mode === 'full') ev.push({ type: 'trace', t, kind: 'chest', value: Math.sin(2 * Math.PI * (truth.breathing / 60) * s) });
  }

  const metrics: Metric[] = mode === 'quick' ? ['pulse'] : ['pulse', 'breathing', 'hrv'];
  for (let s = 1; s <= durS; s++) {
    for (const m of metrics) {
      const w = WIN[m];
      const filled = s >= w + 1;
      let value = truth[m] + 0.6 * g();
      // documented failure modes: the SDK can stay confident while these happen
      if (m === 'pulse' && scenario === 'flicker72' && s >= 3) value = truth.pulse + (72 - truth.pulse) * Math.min(1, (s - 3) / 10) + 0.4 * g();
      if (m === 'breathing' && scenario === 'talking' && s >= 37 && s < 70) value = 19 + g();
      if (m === 'pulse' && scenario === 'chewing' && s >= 14 && s < 40) value = 84 + g();
      const confidence = filled ? 70 + 8 * r() : 0;
      ev.push({ type: 'rate', t: Math.round(s * US), metric: m, value, confidence, stable: confidence >= STABLE_AT[m] });
    }
  }
  ev.sort((a, b) => a.t - b.t);
  return [header, ...ev];
}

export function toJsonl(lines: TraceLine[]): string {
  return lines.map((l) => JSON.stringify(l)).join('\n') + '\n';
}
